head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50104";
scwin.upd_templateFile = null;
scwin.upd_styleFile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_fssForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.upd_templateFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_templateFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_templateFile"]');
        scwin.upd_styleFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_styleFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_styleFile"]');
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50104.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_35_onclick
 * @description img_35 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_35_onclick = async function(e){
    try {
        await scwin.transform()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50104.img_35_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Transform
 * @description Transform 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Transform = async function () {
    const sbmOptions = {
        id: "tx_fn_Transform",
        method: "post",
        action: "/filing/fssForm.do",
        ref: "dma_TransformReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name transform
 * @description transform 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.transform = async function () {
    if (!await scwin.validate()) {
        return;
    }
    const _url = "about:blank";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=680,height=700";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    const popWin = $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), String((typeof _props !== 'undefined' ? _props : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "fssFormPop", scrollbars: true, resizable: true, width: "680", height: "700", type: "pageFramePopup" }, { id: '' }) : { id: "fssFormPop", scrollbars: true, resizable: true, width: "680", height: "700", type: "pageFramePopup" }), {});
    $c.util.getComponent('dma_TransformReq').set('method', "viewFssForm");
    scwin.form_fssForm.action = "/filing/document.fssForm.do";
    scwin.form_fssForm.target = "fssFormPop";
    await scwin.tx_fn_Transform();
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    if (String(($c.util.getComponent("upd_templateFile") || { getValue: function () { return ''; } }).getValue() || '').replace(/\s/g, '') === '') { await $c.win.alert("서식파일을 입력해 주세요."); ($c.util.getComponent("upd_templateFile") && $c.util.getComponent("upd_templateFile").setFocus ? $c.util.getComponent("upd_templateFile").setFocus() : ($c.util.getComponent("upd_templateFile") && $c.util.getComponent("upd_templateFile").focus ? $c.util.getComponent("upd_templateFile").focus() : void 0)); return false; }
    return true;
};

/**
 * @method
 * @name setFssFormHtml
 * @description set Fss Form Html 처리
 * @param {*} formHtml formHtml
 * @returns {void}
 * @hidden N
 */
scwin.setFssFormHtml = function (formHtml) {
    ($c.util.getComponent('fssFormDiv') && $c.util.getComponent('fssFormDiv').setValue) ? $c.util.getComponent('fssFormDiv').setValue(formHtml) : (($c.util.getComponent('fssFormDiv') && $c.util.getComponent('fssFormDiv').setText) ? $c.util.getComponent('fssFormDiv').setText(formHtml) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'fssFormDiv'), void (formHtml)));
};
